"""Independent structural checker for the export operation."""
import json, re, sys

def parse_set(text):
    text = text.strip()
    assert text.startswith("{") and text.endswith("}"), text
    body = text[1:-1].strip()
    if not body: return set()
    return set(int(x) for x in body.split(","))

def parse_tuple(text):
    text = text.strip()
    assert text.startswith("<<") and text.endswith(">>"), text
    body = text[2:-2].strip()
    if not body: return []
    return [x.strip().strip('"') for x in body.split(",")]

def check(req, resp):
    errs = []
    mod = resp["module"]
    lines = [l.strip() for l in mod.splitlines() if l.strip()]
    if lines[0] != "---- MODULE ModelData ----": errs.append("bad header: %r" % lines[0])
    if lines[-1] != "====": errs.append("bad footer: %r" % lines[-1])
    if lines[1] != "EXTENDS Integers, Sequences, FiniteSets": errs.append("bad extends: %r" % lines[1])
    defs = lines[2:-1]
    names = ["Nodes","Initial","Edges","ActionNames","WFIds","SFIds","SafeNodes","DoneNodes"]
    if len(defs) != 8: errs.append("expected 8 definitions, got %d" % len(defs))
    else:
        for d, nm in zip(defs, names):
            if not d.startswith(nm + " == "): errs.append("definition order/name: %r" % d)
    vals = {}
    for d in defs:
        k, _, v = d.partition(" == ")
        vals[k] = v.strip()
    states = req["states"]; edges = req["edges"]; start = req["start"]; fairness = req["fairness"]
    N = len(states)
    allnames = sorted({e[1] for e in edges} | {f["action"] for f in fairness})
    idx = {n:i+1 for i,n in enumerate(allnames)}
    if vals.get("Nodes") != "0..%d" % (N-1): errs.append("Nodes: %r" % vals.get("Nodes"))
    if vals.get("Initial") != str(start): errs.append("Initial: %r" % vals.get("Initial"))
    got_edges = parse_set(vals["Edges"])
    want_edges = set("<<%d,%d,%d>>" % (e[0], idx[e[1]], e[2]) for e in edges)
    if got_edges != want_edges: errs.append("Edges mismatch: %r vs %r" % (sorted(got_edges)[:4], sorted(want_edges)[:4]))
    got_names = parse_tuple(vals["ActionNames"])
    if got_names != allnames: errs.append("ActionNames: %r vs %r" % (got_names, allnames))
    wf = set(idx[f["action"]] for f in fairness if f["mode"]=="weak")
    sf = set(idx[f["action"]] for f in fairness if f["mode"]=="strong")
    if parse_set(vals["WFIds"]) != wf: errs.append("WFIds: %r vs %r" % (vals["WFIds"], sorted(wf)))
    if parse_set(vals["SFIds"]) != sf: errs.append("SFIds: %r vs %r" % (vals["SFIds"], sorted(sf)))
    # predicates
    inputs = req["inputs"]
    P = len(inputs); R = len(inputs[0]) if P else 0
    D = len(inputs[0][0]) if (P and R) else 0
    exp = []
    for q in range(R):
        acc=[0]*D
        for r in range(P):
            for i in range(D): acc[i]+=inputs[r][q][i]
        exp.append(acc)
    safe=[];done=[]
    for s in states:
        ok=True
        for r in range(P):
            for q,v in enumerate(s["delivered"][r]):
                if v!=exp[q]: ok=False
        for sl in s["slots"]:
            acc=[0]*D
            for r in sl["ranks"]:
                for i in range(D): acc[i]+=inputs[r][sl["seq"]][i]
            if acc!=sl["sum"]: ok=False
        safe.append(ok)
        done.append(all(len(s["delivered"][r])==R for r in range(P)))
    want_safe = set(str(i) for i in range(N) if safe[i])
    want_done = set(str(i) for i in range(N) if done[i])
    if parse_set(vals["SafeNodes"]) != want_safe: errs.append("SafeNodes mismatch")
    if parse_set(vals["DoneNodes"]) != want_done: errs.append("DoneNodes mismatch")
    cfg = resp["config"].split()
    want_cfg = ["SPECIFICATION","Spec","INVARIANT","Safety","PROPERTY","Termination","CHECK_DEADLOCK","FALSE"]
    if cfg != want_cfg: errs.append("config: %r" % cfg)
    return errs

if __name__ == "__main__":
    reqs = [json.loads(l) for l in open(sys.argv[1])]
    resps = [json.loads(l) for l in open(sys.argv[2])]
    bad=0
    for req, resp in zip(reqs,resps):
        if req.get("op") != "export": continue
        e = check(req, resp)
        if e:
            bad+=1; print("FAIL", e); print(json.dumps(req)[:300]); print(resp["module"][:500])
    print("export checks done, failures:", bad)
